class Codec:
    def serialize(self, root):
        parts = []

        def preorder(node):
            if not node:
                parts.append("None")
                return
            parts.append(str(node.val))
            preorder(node.left)
            preorder(node.right)

        preorder(root)
        return ",".join(parts)

    def deserialize(self, data):
        values = data.split(",")
        pos = 0  # index of the next token to read

        def build_tree():
            nonlocal pos
            value = values[pos]
            pos += 1
            if value == "None":
                return None

            root = TreeNode(int(value))
            root.left = build_tree()
            root.right = build_tree()
            return root

        return build_tree()
